+#!/usr/bin/env node
+/**
+ * verify-no-regen.js: verificador de NO-REGENERACIÓN de los roles curriculares retirados
+ * (TICKET-133 / UPONE-1615, S5.T4).
+ *
+ * CONTEXTO: en S5 se retiraron nombres de rol viejos del dominio curricular. Este CLI de SOLO
+ * LECTURA asierta que esos nombres NO reaparecieron en la DB tras el reset + sync. Está pensado
+ * para correrse DESPUÉS de dos syncs consecutivos (reset + sync 2×): la garantía real de la
+ * regla de no-regeneración es que un segundo sync sobre una DB ya sincronizada tampoco los
+ * resucita. El auto-create de roles desde layout fue eliminado en UPONE-1699 (dbSync ahora
+ * reporta el rol faltante y esconde el layout con el sentinel; nunca lo crea), así que la
+ * expectativa es 0 en todas las fases.
+ *
+ * TRES NOMBRES RETIRADOS que se verifican (todos deben dar 0):
+ *   1. "GestorCurricular"  — core_Role/perfil huérfano retirado en S5.T2 (ver retire-orphan-role.js).
+ *   2. "LectorCurricular"  — fixture de rol de mod (test de sync modRoles); el sync no debe crearlo.
+ *   3. "GestorCurricular"  — fixture de rol de mod (test de sync plat15Config/navByRole); ídem.
+ * Los ids 1 y 3 comparten el string "GestorCurricular": son identidades lógicas distintas (rol
+ * huérfano real vs. fixture de sync) que colapsan al mismo nombre de rol en la DB. Se verifica
+ * cada string una vez por tabla, y se reporta por identidad para dejar traza explícita.
+ *
+ * Cobertura por tabla: un rol de mod puede materializar como core_Role (rol institucional) o como
+ * core_ModRole (perfil). Se consulta AMBAS por cada nombre para que la no-regeneración cubra las
+ * dos formas. Reaparecer en cualquiera de las dos = regresión.
+ *
+ * Conexión: reutiliza el patrón read-only de retire-orphan-role.js (tenantManager de
+ * object-manager + DATABASE_URL del .env). NO hardcodea credenciales, NO muta nada.
+ *
+ * Exit codes: 0 = los tres nombres dan 0 en ambas tablas (no-regeneración OK);
+ *             2 = al menos un nombre reapareció (regresión — se nombra cuál y en qué tabla);
+ *             3 = error de conexión/lectura.
+ *
+ * Uso:
+ *   node scripts/rbac/verify-no-regen.js
+ *   node scripts/rbac/verify-no-regen.js --tenant=UPU
+ *   node scripts/rbac/verify-no-regen.js --json   # emite el reporte como JSON a stdout
+ */
+
+import { pathToFileURL } from 'url';
+import path from 'path';
+import dotenv from 'dotenv';
+import tenantManager from '../../../../object-manager/src/services/tenantManager.js';
+
+// El .env vive en object-manager (ahí está DATABASE_URL). Cargarlo explícitamente porque el cwd
+// puede ser el del mod, no el del backend.
+const OBJECT_MANAGER_DIR = new URL('../../../../object-manager/', import.meta.url);
+dotenv.config({ path: path.join(OBJECT_MANAGER_DIR.pathname, '.env') });
+
+const DEFAULT_TENANT = process.env.TENANT_ID || 'UPU';
+
+// Las tres identidades lógicas retiradas. `name` es el string real del rol en la DB; `label`
+// distingue la identidad para el reporte (dos comparten "GestorCurricular").
+const RETIRED_IDENTITIES = [
+  { label: 'GestorCurricular (core_Role/perfil huérfano · S5.T2)', name: 'GestorCurricular' },
+  { label: 'LectorCurricular (fixture rol de mod · sync modRoles)', name: 'LectorCurricular' },
+  { label: 'GestorCurricular (fixture rol de mod · sync plat15Config)', name: 'GestorCurricular' },
+];
+
+// Exit codes explícitos.
+const EXIT_OK = 0;
+const EXIT_REGRESSION = 2;
+const EXIT_READ_ERROR = 3;
+
+function parseArgs(argv) {
+  const get = (flag) => argv.find((a) => a.startsWith(`${flag}=`))?.split('=').slice(1).join('=');
+  return {
+    tenantId: get('--tenant') || DEFAULT_TENANT,
+    json: argv.includes('--json'),
+  };
+}
+
+/**
+ * Cuenta, SOLO LECTURA, cuántas filas hay para un nombre de rol en core_Role y core_ModRole.
+ * @param {object} prisma - cliente Prisma scoped al tenant
+ * @param {string} name - nombre exacto del rol retirado
+ * @returns {Promise<{ coreRole: number, coreModRole: number }>}
+ */
+async function countByName(prisma, name) {
+  const [coreRole, coreModRole] = await Promise.all([
+    prisma.core_Role.count({ where: { name } }),
+    prisma.core_ModRole.count({ where: { name } }),
+  ]);
+  return { coreRole, coreModRole };
+}
+
+/**
+ * Corre la verificación read-only sobre los tres nombres retirados. Devuelve el reporte
+ * serializable. No muta nada.
+ */
+async function verifyNoRegen(prisma, tenantId) {
+  const checkedAt = new Date().toISOString();
+  // Cachear por string de nombre: dos identidades comparten "GestorCurricular", una sola query.
+  const countsByName = new Map();
+
+  const results = [];
+  for (const identity of RETIRED_IDENTITIES) {
+    if (!countsByName.has(identity.name)) {
+      countsByName.set(identity.name, await countByName(prisma, identity.name));
+    }
+    const counts = countsByName.get(identity.name);
+    const total = counts.coreRole + counts.coreModRole;
+    results.push({
+      label: identity.label,
+      name: identity.name,
+      coreRole: counts.coreRole,
+      coreModRole: counts.coreModRole,
+      total,
+      regenerated: total > 0,
+    });
+  }
+
+  const regressions = results.filter((r) => r.regenerated);
+  return {
+    meta: { tenantId, checkedAt, ticket: 'UPONE-1615 / TICKET-133 · S5.T4' },
+    results,
+    regressions: regressions.map((r) => ({ label: r.label, name: r.name, coreRole: r.coreRole, coreModRole: r.coreModRole })),
+    ok: regressions.length === 0,
+  };
+}
+
+function printSummary(report) {
+  const { meta, results, ok } = report;
+  console.log(`\n${'='.repeat(78)}`);
+  console.log(`Verificación de NO-REGENERACIÓN de roles retirados — tenant ${meta.tenantId}`);
+  console.log('='.repeat(78));
+  for (const r of results) {
+    const flag = r.regenerated ? '❌ REAPARECIÓ' : '✅ 0';
+    console.log(`   ${flag}  ${r.label}`);
+    console.log(`         core_Role=${r.coreRole}  core_ModRole=${r.coreModRole}  (total ${r.total})`);
+  }
+  console.log('-'.repeat(78));
+  if (ok) {
+    console.log('✅ Los tres nombres retirados dan 0 en ambas tablas: NO hubo regeneración.');
+  } else {
+    console.log('❌ Regresión: uno o más nombres retirados reaparecieron (ver arriba).');
+  }
+}
+
+async function runCli() {
+  const { tenantId, json } = parseArgs(process.argv.slice(2));
+
+  let prisma;
+  try {
+    prisma = await tenantManager.getClient(tenantId);
+  } catch (error) {
+    console.error(`❌ No se pudo abrir la conexión al tenant ${tenantId}: ${error.message}`);
+    process.exit(EXIT_READ_ERROR);
+  }
+
+  let report;
+  try {
+    report = await verifyNoRegen(prisma, tenantId);
+  } catch (error) {
+    console.error(`❌ Falló la verificación de no-regeneración: ${error.message}`);
+    await tenantManager.disconnectAll();
+    process.exit(EXIT_READ_ERROR);
+  }
+
+  if (json) {
+    console.log(JSON.stringify(report, null, 2));
+  } else {
+    printSummary(report);
+  }
+
+  await tenantManager.disconnectAll();
+  process.exit(report.ok ? EXIT_OK : EXIT_REGRESSION);
+}
+
+function isMainModule() {
+  const entrypoint = process.argv[1];
+  return Boolean(entrypoint) && import.meta.url === pathToFileURL(entrypoint).href;
+}
+
+if (isMainModule()) {
+  runCli().catch(async (error) => {
+    await tenantManager.disconnectAll();
+    console.error(error);
+    process.exit(EXIT_READ_ERROR);
+  });
+}
+
+export { verifyNoRegen, countByName, parseArgs, RETIRED_IDENTITIES };
```
